function results = opf_case30Q(bus_PD_7, bus_QD_8, bus_VMIN_4)
    define_constants;
    mpc = loadcase('case30Q');

    %% Bus 7: reduce active demand (VPP-driven peak shaving)
    bus7_idx = find(mpc.bus(:, BUS_I) == 7);
    pd0_bus7 = mpc.bus(bus7_idx, PD);
    mpc.bus(bus7_idx, PD) = bus_PD_7;
