    %% Bus 8: reduce reactive demand (demand-side participation)
    bus8_idx = find(mpc.bus(:, BUS_I) == 8);
    qd0_bus8 = mpc.bus(bus8_idx, QD);
    mpc.bus(bus8_idx, QD) = bus_QD_8;
