    mpc.bus(bus4_idx, VMIN) = bus_VMIN_4;
    assert(bus_VMIN_4 >= vmin0_bus4, 'Parameter must increase according to scenario');

    mpopt = mpoption('opf.violation', 1e-8, 'opf.ac.solver', 'MIPS');
    results = runopf(mpc, mpopt);
    printpf(results);
end

