clear; clc;
define_constants;

%% ========================= Load base case =========================
mpc = loadcase('case118');

%% ========================= Parameter modifications =========================
% Bus 78, BS set to -0.1
mpc.bus(78, BS) = -0.1;

%% ========================= Solver options =========================
mpopt = mpoption('verbose', 1, 'out.all', 0);
mpopt = mpoption(mpopt, 'model', 'AC');
mpopt = mpoption(mpopt, 'opf.ac.solver', 'MIPS');
mpopt = mpoption(mpopt, 'opf.violation', 1e-6);

nb  = size(mpc.bus, 1);
ng0 = size(mpc.gen, 1);   % original number of generators

%% ========================= Add virtual generators for load shedding =========================
load_buses = find(mpc.bus(:, PD) > 0);
nl = length(load_buses);

% Make compatible with any gen column count
ncol_gen = size(mpc.gen, 2);
new_gen  = zeros(nl, ncol_gen);

for k = 1:nl
    b = load_buses(k);
    Pd_k = mpc.bus(b, PD);

    % Copy a template row to preserve extra columns
    g = mpc.gen(1, :);

    g(GEN_BUS)    = b;
    g(PG)         = 0;
    g(QG)         = 0;
    g(QMAX)       = 0;
    g(QMIN)       = 0;
    g(VG)         = 1.0;
    g(GEN_STATUS) = 1;
    g(PMAX)       = Pd_k;   % max shed = original active load
    g(PMIN)       = 0;      % min shed = 0

    new_gen(k, :) = g;
end

mpc.gen = [mpc.gen; new_gen];
ng = size(mpc.gen, 1);
shed_gen_idx = (ng0+1:ng)';

%% ========================= Add cost for shedding generators =========================
% MATPOWER polynomial cost row format: [MODEL STARTUP SHUTDOWN NCOST c2 c1 c0]
old_cost = mpc.gencost;
ncol_gc  = size(old_cost, 2);

% Penalty coefficients (can be tuned)
p_cost = 100  * ones(nl, 1);   % c0
q_cost = 1000 * ones(nl, 1);   % c1
r_cost = 5000 * ones(nl, 1);   % c2

new_cost = zeros(nl, ncol_gc);
new_cost(:, 1) = 2;   % polynomial
new_cost(:, 2) = 0;   % startup
new_cost(:, 3) = 0;   % shutdown
new_cost(:, 4) = 3;   % quadratic: c2, c1, c0
new_cost(:, 5) = r_cost;
new_cost(:, 6) = q_cost;
new_cost(:, 7) = p_cost;

mpc.gencost = [old_cost; new_cost];

%% ========================= Solve AC-OPF =========================
results = runopf(mpc, mpopt);

if ~results.success
    error('AC-OPF with load shedding did not converge.');
end

%% ========================= Post-processing: shedding summary =========================
fprintf('\n=== AC-OPF with Load Shedding (case118) ===\n');
fprintf('Total objective = %.6f\n', results.f);

Pg_all = results.gen(:, PG);
Lshd   = Pg_all(shed_gen_idx);  % shedding amounts
orig_load = mpc.bus(load_buses, PD);
remain_load = orig_load - Lshd;

total_orig   = sum(orig_load);
total_shed   = sum(Lshd);
total_remain = total_orig - total_shed;

shed_cost = sum(p_cost + q_cost .* Lshd + r_cost .* (Lshd.^2));

fprintf('\n-- Load Shedding Summary --\n');
fprintf('  Total original load   = %10.3f MW\n', total_orig);
fprintf('  Total shed load       = %10.3f MW\n', total_shed);
fprintf('  Total remaining load  = %10.3f MW\n', total_remain);
fprintf('  Overall shed ratio    = %10.4f %%\n', 100 * total_shed / total_orig);
fprintf('  Load shedding cost    = %10.6f (from cost function)\n', shed_cost);

fprintf('\nBus  OrigLoad(MW)  ShedLoad(MW)  RemainLoad(MW)  ShedRatio(%%)\n');
for k = 1:nl
    b = load_buses(k);
    if orig_load(k) > 0
        ratio = 100 * Lshd(k) / orig_load(k);
    else
        ratio = 0;
    end
    fprintf('%3d  %12.3f  %11.3f  %14.3f  %11.4f\n', ...
        b, orig_load(k), Lshd(k), remain_load(k), ratio);
end

